calculate.script:
// Scenario 1: this field's own bound value isn't available here since
// bind match="none" -- instead reference the sibling UnitPrice field and
// apply a fixed 8% tax rate. Expected: 19.99 * 1.08 = 21.5892, displayed
// as "21.5892" (confirmed -- the engine does not auto-round display text).
var price = xfa.resolveNode("UnitPrice").rawValue;
this.rawValue = price * 1.08;

// Scenario 2: xfa.resolveNode cross-field reference + string concatenation.
// Expected: "Purchase Order PO-1042 for Acme Robotics"
var name = xfa.resolveNode("CustomerName").rawValue;
var po = xfa.resolveNode("PoNumber").rawValue;
this.rawValue = "Purchase Order " + po + " for " + name;

// Scenario 3 (highest-risk): each of the 3 Line instances below computes ITS
// OWN total from ITS OWN Qty/UnitCost siblings -- not a shared/cached value
// from a different instance. This is the JS-engine equivalent of the
// occur+ValidateFailed shared-state bug already found and fixed for
// FormCalc earlier this project; confirmed all 3 rows compute independently
// (50.00 / 90.00 / 89.75), no shared-state bleed.
var qty = xfa.resolveNode("Qty").rawValue;
var cost = xfa.resolveNode("UnitCost").rawValue;
this.rawValue = qty * cost;
